from __future__ import annotations


class DonguHatasi(ValueError):
    def __init__(self, dongu: list[str]):
        self.dongu = dongu
        super().__init__("Döngü tespit edildi: " + " -> ".join(dongu))


def _rotate_to_min(cycle: list[str]) -> list[str]:
    i = cycle.index(min(cycle))
    return cycle[i:] + cycle[:i]


def kurulum_sirasi(deps: dict[str, list[str]]) -> list[str]:
    # Tüm paketler (yalnızca bağımlılık olarak geçenler dahil)
    packages: set[str] = set(deps)
    for d in deps.values():
        for p in d:
            packages.add(p)

    # Aynı bağımlılıkların tekrarını kaldır, her paketi kendinden ayır (self-loop döngüdür)
    unique_deps: dict[str, list[str]] = {}
    for node, ds in deps.items():
        u = []
        seen = set()
        for d in ds:
            if d == node:
                raise DonguHatasi([node])
            if d not in seen:
                seen.add(d)
                u.append(d)
        unique_deps[node] = u

    # reverse: p -> kendisini bağımlılık olarak isteyen paketler
    rev: dict[str, list[str]] = {p: [] for p in packages}
    indeg = {}
    for node in packages:
        deps_list = unique_deps.get(node, [])
        indeg[node] = len(deps_list)
        for d in deps_list:
            rev[d].append(node)

    # En-büyük-bağımlılık-önce (giriş derecesi küçük olanlar önce) -- Kahn varyantı.
    import heapq
    heap = []
    for p in packages:
        if indeg[p] == 0:
            heapq.heappush(heap, (-p, p))
    result: list[str] = []
    while heap:
        _, node = heapq.heappop(heap)
        result.append(node)
        for m in rev[node]:
            indeg[m] -= 1
            if indeg[m] == 0:
                heapq.heappush(heap, (-m, m))

    if len(result) != len(packages):
        # Kalan düğümler döngü içindedir veya döngüden bağımlıdır.
        remaining = set(packages) - set(result)

        def dfs(start: str) -> list[str] | None:
            stack: list[tuple[int, str]] = [(0, start)]
            path: list[str] = []
            pos: dict[str, int] = {}
            while stack:
                idx, n = stack[-1]
                if idx == 0:
                    path.append(n)
                    pos[n] = len(path) - 1
                advanced = False
                for d in unique_deps.get(n, []):
                    if d not in remaining:
                        continue
                    i = pos.get(d)
                    if i is not None and i >= 0:
                        return _rotate_to_min(path[i:])
                    stack.append((1, d))
                    advanced = True
                    break
                if not advanced:
                    path.pop()
                    del pos[n]
                    stack.pop()
            return None

        for p in sorted(remaining):
            cycle = dfs(p)
            if cycle is not None:
                raise DonguHatasi(cycle)
        # (Ulaşılabilirlik garantisi sayesinde buraya gelinmez.)
        raise AssertionError("İç tutarsızlık")

    return result

