# bağımsız referansla determinizm (küçük örnekler)
def ref(deps):
    pk=set(deps); [pk.update(v) for v in deps.values()]
    u={}
    for k,ds in deps.items():
        s=[];seen=set()
        for d in ds:
            if d!=k and d not in seen: seen.add(d);s.append(d)
        u[k]=s
    indeg={p:len(u.get(p,[])) for p in pk}
    ready=sorted([p for p in pk if indeg[p]==0]); out=[]
    while ready:
        node=ready.pop(0); out.append(node)
        for m in sorted(pk):
            if m!=node and node in u[m]:
                indeg[m]-=1
                if indeg[m]==0: ready.append(m)
        ready.sort()
    return out

